\set ON_ERROR_STOP on
\timing on
CREATE FUNCTION pg_temp.assert_zero(label text, query text) RETURNS void LANGUAGE plpgsql AS $$ DECLARE n numeric; BEGIN FOR n IN EXECUTE query LOOP IF n <> 0 THEN RAISE EXCEPTION '%: % failures', label, n; END IF; END LOOP; RAISE NOTICE 'PASS: %', label; END $$;
SELECT pg_temp.assert_zero('27 registered tables', $query$SELECT abs(count(*) - 27) FROM public.pl_direct_tables WHERE schema_name='mule_temporal'$query$);
SELECT pg_temp.assert_zero('one vertex per payment', $query$SELECT abs((SELECT count(*) FROM mule_temporal."mt_Payment_Transaction") + (SELECT count(*) FROM mule_temporal."mt_Zelle_Transfer") - (SELECT count(*) FROM transactions))$query$);
SELECT pg_temp.assert_zero('exclusive event types', $query$SELECT count(*) FROM mule_temporal."mt_Payment_Transaction" p JOIN mule_temporal."mt_Zelle_Transfer" z ON p.transaction_id=z.transfer_id$query$);
SELECT pg_temp.assert_zero('both rails exercised', $query$SELECT CASE WHEN (SELECT count(*) FROM mule_temporal."mt_Payment_Transaction") > 0 AND (SELECT count(*) FROM mule_temporal."mt_Zelle_Transfer") > 0 THEN 0 ELSE 1 END$query$);
SELECT pg_temp.assert_zero('Party identity and clock', $query$SELECT count(*)-count(DISTINCT id) + count(*) FILTER(WHERE first_seen_seq::numeric <= 0) FROM mule_temporal."mt_Party"$query$);
SELECT pg_temp.assert_zero('Party opaque IDs', $query$SELECT count(*) FROM mule_temporal."mt_Party" WHERE id !~ '^[patdih]_[0-9a-f]{32}$'$query$);
