SELECT 'payments' AS metric, count(*) FROM transactions UNION ALL SELECT 'zelle',count(*) FROM mule_temporal."mt_Zelle_Transfer" UNION ALL SELECT 'zelle_fraud',count(*) FROM mule_temporal."mt_Zelle_Transfer" WHERE fraud_label='1' UNION ALL SELECT 'closed_device_tenures',count(*) FROM mule_temporal."mt_Party_Uses_Device" WHERE valid_to_seq <> '0';
SELECT 'temporal_dataset_validation_passed' AS result;
